	;;
    -q | --quiet)
	quiet=y
	noprogress=y
	shift
	;;
	--accept)
	accept=y
	shift
	;;
    --info)
	echo Identification: "$label"
	echo Target directory: "$targetdir"
	echo Uncompressed size: 18920 KB
	echo Compression: gzip
	if test x"n" != x""; then
	    echo Encryption: n
	fi
